        if (sectionId == (byte)expectedSection)
        {
            sectionOffset = offset;
            sectionEnd = currentSectionEnd;
            return true;
        }

        offset = currentSectionEnd;
    }

    sectionOffset = 0;
    sectionEnd = 0;
    return false;
}
