internal static ZipCryptoKeys create_key(ReadOnlySpan<char> password)
{
    // Initialize keys with standard ZipCrypto initial values
    uint key0 = 305419896;
    uint key1 = 591751049;
    uint key2 = 878082192;

    // Feed the password's UTF-8 bytes into the key schedule. UTF-8 (rather than ASCII)
